{
  "requirement_definitions": [
    {
      "id": "DMSR-6957",
      "title": "Bias Residual Image",
      "text": "The DMS shall construct on an as-needed basis an image that corrects for any temporally stable bias structure that remains after overscan correction. The Bias Residual shall be constructed from multiple, zero-second exposures where the overscan correction has been applied."
    },
    {
      "id": "DMSR-7349",
      "title": "Crosstalk Correction Matrix",
      "text": "The DMS shall, on an as-needed basis, determine from appropriate calibration data what fraction of the signal detected in any given ampliﬁer on each sensor in the focal plane appears in any other ampliﬁer, and shall record that fraction in a correction matrix. The applicability of the correction matrix shall be veriﬁed in production processing on science data."
    },
    {
      "id": "DMSR-1633",
      "title": "Dark Current Correction Frame",
      "text": "The DMS shall produce on an as-needed basis a dark current correction image, which is constructed from multiple, closed-shutter exposures of appropriate duration. The eﬀectiveness of the Dark Correction shall be veriﬁed in production processing on science data."
    },
    {
      "id": "DMSR-7466",
      "title": "Monochromatic Flatﬁeld Data Cube",
      "text": "The DMS shall produce on an as-needed basis an image that corrects for the color-dependent, pixel-to-pixel non-uniformity in the detector response. The images in the cube shall be constructed from exposures at multiple wavelengths of a uniformly illuminated source. The eﬀectiveness of the ﬂat-ﬁeld shall be veriﬁed in production processing on science data."
    },
    {
      "id": "DMSR-7118",
      "title": "Illumination Correction Frame",
      "text": "The DMS shall produce on an as-needed basis an image that corrects for the non-uniform illumination of the ﬂat-ﬁeld calibration apparatus on the focal plane. The eﬀectiveness of the Illumination Correction shall be veriﬁed in production processing on science data."
    },
    {
      "id": "DMSR-4608",
      "title": "Fringe Correction Frame",
      "text": "The DMS shall produce on an as-needed basis an image that corrects for detector fringing. The eﬀectiveness of the Fringe Correction shall be veriﬁed in production processing on science data."
    },
    {
      "id": "DMSR-8515",
      "title": "Processing of Data From Special Programs",
      "text": "It shall be possible for special programs to trigger their own data processing recipes. It shall also be possible for special programs data to be processed with the promptand/or annual-release pipelines alongside data from the main survey."
    }
  ],
  "allocation_entries": []
}
